import urllib.parse, urllib.request, sys

def get(url):
    try:
        with urllib.request.urlopen(url, timeout=30) as r:
            return r.read().decode('utf-8', 'ignore')
    except Exception as e:
        print('ERR', url, e, file=sys.stderr)
        return ''

